1	// Package indexroom implements chain ingestion with reorg handling and
2	// consistent paginated transaction queries over the main chain.
3	package indexroom
4	
5	import "sync"
6	
7	// Block is one ingested block with its transactions.
8	type Block struct {
9		Height int64
10		Hash   string
11		Parent string
12		Txs    []string
13	}
14	
15	// Index is the durable chain view.
16	//
17	// Append, Reorg, QueryTxs, Export, and Restore are safe for concurrent use;
18	// the exported fields are meant for read-only inspection after all calls
19	// have finished.
20	type Index struct {
21		Blocks map[int64]Block
22		ByHash map[string]int64
23		Tip    int64
24	
25		mu  sync.Mutex
26		key [32]byte
27	}
28	
29	// New returns an empty index.
30	func New() *Index {
31		return &Index{Blocks: map[int64]Block{}, ByHash: map[string]int64{}, key: newKey()}
32	}
33	
34	// Append accepts a block only when it extends the current tip, keeping the
35	// chain linear. Re-submitting a block identical to one already on the main
36	// chain is a successful no-op. A rejected append leaves the index untouched.
37	func (index *Index) Append(block Block) error {
38		index.mu.Lock()
39		defer index.mu.Unlock()
40		return index.appendLocked(block)
41	}
42	
43	func (index *Index) appendLocked(block Block) error {
44		if block.Hash == "" {
45			return errInvalid("block needs a hash")
46		}
47		if index.Tip == 0 {
48			// Empty index: only the first block at height 1 is accepted; its
49			// parent becomes the chain start identifier and need not be indexed.
50			if block.Height != 1 {
51				return errInvalid("first block must be at height 1")
52			}
53			index.storeLocked(block)
54			return nil
55		}
56		if old, exists := index.Blocks[block.Height]; exists {
57			if sameBlock(old, block) {
58				return nil
59			}
60			return errInvalid("height already indexed with different content")
61		}
62		if block.Height != index.Tip+1 {
63			return errInvalid("block height must extend the current tip")
64		}
65		if block.Parent != index.Blocks[index.Tip].Hash {
66			return errInvalid("parent does not match the current tip")
67		}
68		if _, exists := index.ByHash[block.Hash]; exists {
69			return errInvalid("hash already indexed at another height")
70		}
71		index.storeLocked(block)
72		return nil
73	}
74	
75	// Reorg replaces the tip range with an alternate branch and reports the
76	// dropped old heights in ascending order. The branch is validated in full
77	// before anything is applied, so a rejected reorg leaves the index exactly
78	// as it was. Heights whose old block is identical to the new one are not
79	// reported; re-submitting the branch already in effect returns an empty list.
80	func (index *Index) Reorg(blocks []Block) ([]int64, error) {
81		index.mu.Lock()
82		defer index.mu.Unlock()
83	
84		if len(blocks) == 0 {
85			return nil, errInvalid("empty branch")
86		}
87		ancestor, ok := index.ByHash[blocks[0].Parent]
88		if !ok {
89			return nil, errInvalid("branch parent is unknown")
90		}
91		if blocks[0].Height != ancestor+1 {
92			return nil, errInvalid("branch must start at the ancestor height plus one")
93		}
94		seen := make(map[string]bool, len(blocks))
95		for i, block := range blocks {
96			if block.Hash == "" {
97				return nil, errInvalid("block needs a hash")
98			}
99			if seen[block.Hash] {
100				return nil, errInvalid("duplicate hash inside branch")
101			}
102			seen[block.Hash] = true
103			if height, exists := index.ByHash[block.Hash]; exists && height <= ancestor {
104				return nil, errInvalid("hash conflicts with a retained block")
105			}
106			if i > 0 {
107				prev := blocks[i-1]
108				if block.Height != prev.Height+1 {
109					return nil, errInvalid("branch heights must be consecutive")
110				}
111				if block.Parent != prev.Hash {
112					return nil, errInvalid("branch parent does not match the previous block")
113				}
114			}
115		}
116	
117		// Everything validated; compute the dropped heights before mutating.
118		newTip := blocks[len(blocks)-1].Height
119		dropped := []int64{}
120		for height := ancestor + 1; height <= index.Tip; height++ {
121			if height > newTip {
122				dropped = append(dropped, height)
123				continue
124			}
125			if !sameBlock(index.Blocks[height], blocks[height-blocks[0].Height]) {
126				dropped = append(dropped, height)
127			}
128		}
129		for height := ancestor + 1; height <= index.Tip; height++ {
130			delete(index.ByHash, index.Blocks[height].Hash)
131			delete(index.Blocks, height)
132		}
133		index.Tip = ancestor
134		for _, block := range blocks {
135			index.storeLocked(block)
136		}
137		return dropped, nil
138	}
139	
140	// storeLocked records a validated block, copying its transactions so later
141	// caller-side mutation of the slice cannot alter the stored block.
142	func (index *Index) storeLocked(block Block) {
143		if block.Txs != nil {
144			txs := make([]string, len(block.Txs))
145			copy(txs, block.Txs)
146			block.Txs = txs
147		}
148		index.Blocks[block.Height] = block
149		index.ByHash[block.Hash] = block.Height
150		index.Tip = block.Height
151	}
152	
153	// sameBlock reports whether two blocks are identical: same height, hash,
154	// parent, and transactions in order. An empty tx list equals a missing one.
155	func sameBlock(a, b Block) bool {
156		if a.Height != b.Height || a.Hash != b.Hash || a.Parent != b.Parent {
157			return false
158		}
159		if len(a.Txs) != len(b.Txs) {
160			return false
161		}
162		for i := range a.Txs {
163			if a.Txs[i] != b.Txs[i] {
164				return false
165			}
166		}
167		return true
168	}
169	
170	type errInvalid string
171	
172	func (e errInvalid) Error() string { return string(e) }
173

