1	package indexroom
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"io"
8	)
9	
10	// ErrInvalidSnapshot marks a rejected snapshot document: malformed or
11	// truncated JSON, trailing data after the object, an unknown version,
12	// missing, mistyped, unknown, or duplicated fields, heights that do not
13	// ascend consecutively from 1, an empty or duplicated hash, a broken parent
14	// link, or a tip that disagrees with the block list. A rejected restore
15	// never changes the index.
16	var ErrInvalidSnapshot = errors.New("indexroom: invalid snapshot")
17	
18	// snapshotVersion is the only snapshot layout this package reads and writes.
19	const snapshotVersion = 1
20	
21	// snapshotDoc is the wire form of an exported main chain.
22	type snapshotDoc struct {
23		Version int64           `json:"version"`
24		Tip     int64           `json:"tip"`
25		Blocks  []snapshotBlock `json:"blocks"`
26	}
27	
28	// snapshotBlock is the wire form of one block inside a snapshot.
29	type snapshotBlock struct {
30		Height int64    `json:"height"`
31		Hash   string   `json:"hash"`
32		Parent string   `json:"parent"`
33		Txs    []string `json:"txs"`
34	}
35	
36	// Export writes the current main chain to w as a JSON snapshot: a single
37	// object with version, tip, and the blocks ordered by ascending height, each
38	// carrying its transactions in order. The same main chain always produces
39	// the same bytes, regardless of the reorg, restore, or query history that
40	// led to it. Only blocks in effect at export time appear; nothing the index
41	// once held and later dropped is included.
42	//
43	// Export observes one complete chain state and never modifies the index.
44	// The chain is copied under the lock and serialized afterwards, so queries
45	// and appends proceed while the stream is still being written. A write
46	// failure is reported and leaves the index untouched.
47	func (index *Index) Export(w io.Writer) error {
48		index.mu.Lock()
49		doc := snapshotDoc{
50			Version: snapshotVersion,
51			Tip:     index.Tip,
52			Blocks:  make([]snapshotBlock, 0, int(index.Tip)),
53		}
54		for height := int64(1); height <= index.Tip; height++ {
55			block := index.Blocks[height]
56			txs := make([]string, len(block.Txs))
57			copy(txs, block.Txs)
58			doc.Blocks = append(doc.Blocks, snapshotBlock{
59				Height: block.Height,
60				Hash:   block.Hash,
61				Parent: block.Parent,
62				Txs:    txs,
63			})
64		}
65		index.mu.Unlock()
66	
67		raw, err := json.Marshal(doc)
68		if err != nil {
69			panic(err) // snapshotDoc only contains marshalable fields
70		}
71		n, err := w.Write(raw)
72		if err != nil {
73			return fmt.Errorf("indexroom: export snapshot: %w", err)
74		}
75		if n != len(raw) {
76			return fmt.Errorf("indexroom: export snapshot: %w", io.ErrShortWrite)
77		}
78		return nil
79	}
80	
81	// Restore replaces the whole main chain with the snapshot read from r. The
82	// input must be exactly one snapshot object, optionally followed by
83	// whitespace; every block is validated — including heights ascending from 1,
84	// non-empty unique hashes, and parent linkage — before anything is applied.
85	// The first block's parent is exempt from linkage: it names the chain start
86	// and need not be indexed.
87	//
88	// The replacement takes effect as one complete operation: on success the
89	// index holds exactly the snapshot chain with no leftover heights or hashes,
90	// and on any failure — a read error or an invalid block discovered at the
91	// very end — the current chain and every previously issued cursor remain as
92	// they were. The stream is consumed and validated before the lock is taken,
93	// so the index stays queryable and appendable while the restore is reading.
94	//
95	// After a successful restore, cursors issued earlier by this same index keep
96	// working wherever the pinned range still matches and the tip still covers
97	// it; otherwise continuations fail with ErrQueryChanged as usual.
98	func (index *Index) Restore(r io.Reader) error {
99		tip, blocks, err := parseSnapshot(r)
100		if err != nil {
101			return err
102		}
103		stored := make(map[int64]Block, len(blocks))
104		byHash := make(map[string]int64, len(blocks))
105		for _, block := range blocks {
106			stored[block.Height] = block
107			byHash[block.Hash] = block.Height
108		}
109		index.mu.Lock()
110		index.Blocks = stored
111		index.ByHash = byHash
112		index.Tip = tip
113		index.mu.Unlock()
114		return nil
115	}
116	
117	// parseSnapshot reads and fully validates one snapshot document. It returns
118	// the tip height and the validated blocks in ascending height order.
119	func parseSnapshot(r io.Reader) (int64, []Block, error) {
120		dec := json.NewDecoder(r)
121		tok, err := dec.Token()
122		if err != nil {
123			return 0, nil, classifySnapshotErr(err)
124		}
125		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
126			return 0, nil, invalidSnapshot("snapshot must be a single JSON object")
127		}
128	
129		var (
130			version, tip         int64
131			blocks               []Block
132			haveVersion, haveTip bool
133			haveBlocks           bool
134			seen                 = map[string]bool{}
135		)
136		for dec.More() {
137			key, err := snapshotKey(dec)
138			if err != nil {
139				return 0, nil, err
140			}
141			if seen[key] {
142				return 0, nil, invalidSnapshot("duplicate field %q", key)
143			}
144			seen[key] = true
145			switch key {
146			case "version":
147				if err := dec.Decode(&version); err != nil {
148					return 0, nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
149				}
150				haveVersion = true
151			case "tip":
152				if err := dec.Decode(&tip); err != nil {
153					return 0, nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
154				}
155				haveTip = true
156			case "blocks":
157				blocks, err = parseSnapshotBlocks(dec)
158				if err != nil {
159					return 0, nil, err
160				}
161				haveBlocks = true
162			default:
163				return 0, nil, invalidSnapshot("unknown field %q", key)
164			}
165		}
166		if _, err := dec.Token(); err != nil { // closing '}'
167			return 0, nil, classifySnapshotErr(err)
168		}
169		// Only whitespace may follow the snapshot object.
170		if _, err := dec.Token(); err != io.EOF {
171			if err == nil {
172				return 0, nil, invalidSnapshot("trailing data after the snapshot object")
173			}
174			return 0, nil, classifySnapshotErr(err)
175		}
176	
177		if !haveVersion {
178			return 0, nil, invalidSnapshot("missing field %q", "version")
179		}
180		if !haveTip {
181			return 0, nil, invalidSnapshot("missing field %q", "tip")
182		}
183		if !haveBlocks {
184			return 0, nil, invalidSnapshot("missing field %q", "blocks")
185		}
186		if version != snapshotVersion {
187			return 0, nil, invalidSnapshot("unsupported version %d", version)
188		}
189		lastHeight := int64(0)
190		if len(blocks) > 0 {
191			lastHeight = blocks[len(blocks)-1].Height
192		}
193		if tip != lastHeight {
194			return 0, nil, invalidSnapshot("tip %d does not match the last block height %d", tip, lastHeight)
195		}
196		return tip, blocks, nil
197	}
198	
199	// parseSnapshotBlocks reads the blocks array value, validating heights,
200	// hashes, and parent links as it goes.
201	func parseSnapshotBlocks(dec *json.Decoder) ([]Block, error) {
202		tok, err := dec.Token()
203		if err != nil {
204			return nil, classifySnapshotErr(err)
205		}
206		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
207			return nil, invalidSnapshot("field %q must be an array", "blocks")
208		}
209		blocks := []Block{}
210		seenHash := map[string]bool{}
211		for dec.More() {
212			block, err := parseSnapshotBlock(dec)
213			if err != nil {
214				return nil, err
215			}
216			want := int64(len(blocks) + 1)
217			if block.Height != want {
218				return nil, invalidSnapshot("block height %d out of order, expected %d", block.Height, want)
219			}
220			if block.Hash == "" {
221				return nil, invalidSnapshot("block at height %d has an empty hash", block.Height)
222			}
223			if seenHash[block.Hash] {
224				return nil, invalidSnapshot("duplicate hash %q", block.Hash)
225			}
226			seenHash[block.Hash] = true
227			// The first block's parent names the chain start and is exempt from
228			// linkage; every later block must point at its predecessor.
229			if len(blocks) > 0 && block.Parent != blocks[len(blocks)-1].Hash {
230				return nil, invalidSnapshot("block at height %d does not link to its parent", block.Height)
231			}
232			blocks = append(blocks, block)
233		}
234		if _, err := dec.Token(); err != nil { // closing ']'
235			return nil, classifySnapshotErr(err)
236		}
237		return blocks, nil
238	}
239	
240	// parseSnapshotBlock reads one block object, requiring exactly the fields
241	// height, hash, parent, and txs.
242	func parseSnapshotBlock(dec *json.Decoder) (Block, error) {
243		var block Block
244		tok, err := dec.Token()
245		if err != nil {
246			return block, classifySnapshotErr(err)
247		}
248		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
249			return block, invalidSnapshot("block must be a JSON object")
250		}
251		var haveHeight, haveHash, haveParent, haveTxs bool
252		seen := map[string]bool{}
253		for dec.More() {
254			key, err := snapshotKey(dec)
