393		}
394	}
395	
396	// errReader fails after delivering a valid snapshot prefix.
397	type errReader struct {
398		data []byte
399		err  error
400	}
401	
402	func (r *errReader) Read(p []byte) (int, error) {
403		if len(r.data) == 0 {
404			return 0, r.err
405		}
406		n := copy(p, r.data)
407		r.data = r.data[n:]
408		return n, nil
409	}
410	
411	func TestRestoreReadFailureLeavesIndexUntouched(t *testing.T) {
412		index := txChain(t, []string{"a"}, []string{"b"})
413		blocks, byHash, tip := snapshot(index)
414		boom := errors.New("connection reset")
415		raw := exportString(t, index)
416		err := index.Restore(&errReader{data: []byte(raw[:len(raw)/2]), err: boom})
417		if !errors.Is(err, boom) {
