521	func TestRestoreWhileStreamOpenIndexStaysUsable(t *testing.T) {
522		index := txChain(t, []string{"a"}, []string{"b"})
523		pr, pw := io.Pipe()
524		done := make(chan error, 1)
525		go func() {
526			done <- index.Restore(pr)
527		}()
528		// Deliver only a prefix; the restore is now blocked mid-stream.
529		if _, err := pw.Write([]byte(`{"version":1,"tip":0,`)); err != nil {
530			t.Fatal(err)
531		}
532		// The index stays queryable and appendable while the stream is open.
533		page, err := index.QueryTxs(TxQuery{})
534		if err != nil || page.TotalMatches != 2 {
535			t.Fatalf("query while restore in flight: page=%+v err=%v", page, err)
536		}
537		if err := index.Append(Block{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"c"}}); err != nil {
538			t.Fatalf("append while restore in flight: %v", err)
539		}
540		// Ending the stream early fails the restore without touching the chain.
541		if err := pw.Close(); err != nil {
542			t.Fatal(err)
543		}
544		if err := <-done; !errors.Is(err, ErrInvalidSnapshot) {
545			t.Fatalf("restore err=%v, want ErrInvalidSnapshot", err)
546		}
547		// Only the append changed the chain; the failed restore left no trace.
548		if index.Tip != 3 || len(index.Blocks) != 3 || index.Blocks[3].Hash != "h3" {
549			t.Fatalf("unexpected state: tip=%d blocks=%v", index.Tip, index.Blocks)
550		}
551	}
