	index := New()
	// Exactly 10000 buckets is allowed: width 10000 with step 1.
	stats, err := index.QueryTimeStats(TimeStatsQuery{Start: 0, End: MaxTimeBuckets, StepSeconds: 1})
	if err != nil {
